import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        int total = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            int low = Integer.parseInt(parts[1]);
            int high = Integer.parseInt(parts[2]);

            TreeSet<Integer> values = new TreeSet<>(List.of(low - 1, low, high, high + 1));
            if (high - low >= 2) {
                values.add((low + high) / 2);
            }
            StringBuilder line = new StringBuilder(parts[0]);
            for (int value : values) {
                line.append(' ').append(value);
            }
            System.out.println(line);
            total += values.size();
        }
        System.out.println("件数 " + total);
    }
}

