import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        int failed = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            double target = Double.parseDouble(parts[1]);
            int stopped = Integer.parseInt(parts[2]);
            double allowed = 525600 * (100 - target) / 100;
            boolean ok = stopped <= allowed;
            if (!ok) {
                failed++;
            }
            System.out.printf("%s %.1f %d %s%n", parts[0], allowed, stopped,
                    ok ? "達成" : "未達");
        }
        System.out.println("未達 " + failed);
    }
}

