import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, int[]> ranges = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            ranges.put(parts[0], new int[] {Integer.parseInt(parts[1]),
                    Integer.parseInt(parts[2])});
        }
        int m = Integer.parseInt(sc.nextLine().trim());
        List<String> problems = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            int[] range = ranges.get(parts[0]);
            int value = Integer.parseInt(parts[1]);
            String expected = (value >= range[0] && value <= range[1]) ? "受付" : "拒否";
            if (!expected.equals(parts[2])) {
                problems.add("NG " + parts[0] + " " + value + " " + parts[2]);
            }
        }
        System.out.println(problems.isEmpty() ? "OK" : "NG");
        problems.forEach(System.out::println);
        System.out.println("一致 " + (m - problems.size()) + "/" + m);
    }
}

