import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> required = List.of("正常", "異常", "権限", "上限");
        Map<String, Set<String>> given = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            Set<String> views = new LinkedHashSet<>();
            if (!parts[1].equals("-")) {
                views.addAll(Arrays.asList(parts[1].split(",")));
            }
            given.put(parts[0], views);
        }

        int complete = 0;
        for (Map.Entry<String, Set<String>> entry : given.entrySet()) {
            List<String> missing = new ArrayList<>();
            for (String view : required) {
                if (!entry.getValue().contains(view)) {
                    missing.add(view);
                }
            }
            if (missing.isEmpty()) {
                complete++;
            } else {
                System.out.println(entry.getKey() + " 不足 " + String.join(",", missing));
            }
        }
        System.out.println("そろっている " + complete + "/" + n);
    }
}
